// Fork of "Elementary Torus-Knot Particle" by Chimel. https://shadertoy.com/view/l3GyWG
// 2025-01-11 


#ifdef GL_ES
precision mediump float;
#endif

/*****************************************************
 * 1) ROTATION HELPERS (vec3, float)
 *****************************************************/
vec3 rotateXVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        p.x,
        c*p.y - s*p.z,
        s*p.y + c*p.z
    );
}

vec3 rotateYVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
         c*p.x + s*p.z,
         p.y,
        -s*p.x + c*p.z
    );
}

vec3 rotateZVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        c*p.x - s*p.y,
        s*p.x + c*p.y,
        p.z
    );
}

/*****************************************************
 * 2) GLOBAL CONSTANTS & SETTINGS
 *****************************************************/
#define PI      3.14159265359
#define TWO_PI  6.28318530718

// 3 knots: 0=Trefoil (right), 1=Arcs (middle), 2=Ring (left)
#define KNOT_COUNT       3
#define WIRES_PER_KNOT   2  
// Fork of "The 3 Elementary Knot-Particles" by Chimel. https://shadertoy.com/view/X3Vczd

#define N_SAMPLES        60
#define WIRE_RADIUS      0.040

// Scene scale
#define SCENE_SCALE      1.0

// Spiral spin speed
#define ROT_SPEED        08.0

//-----------------------------------------------------
// Twist factors for each knot
//-----------------------------------------------------
float twistTrefoil = 15.0;  
float twistArcs    = 10.0; 
float twistRing    = 5.0; 

//-----------------------------------------------------
// Middle knot => manual rotation around X,Y,Z of 45° each
//-----------------------------------------------------
const float arcsRotX = 55.0 * PI / 180.0;
const float arcsRotY = 5.0  * PI / 180.0;
const float arcsRotZ = 65.0 * PI / 180.0;

/*****************************************************
 * 3) ARCS (middle), param in [0..4], NOT closed
 *****************************************************/
vec3 arcsRawPos(float t)
{
    float T = mod(t, 4.0);
    float I = floor(T);
    float sf = fract(T);
    float angle;
    vec3 p = vec3(0.0);

    if(I < 0.5)
    {
        // front arc => [0..1]
        angle = -PI*0.5 + PI*sf;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), 0.25);
    }
    else if(I < 1.5)
    {
        // top arc => [1..2], flipped
        angle = -PI + PI*sf;
        p = vec3(-0.25*cos(angle), 0.25, 0.25*sin(angle));
        p = rotateYVec(p, PI*0.5);
    }
    else if(I < 2.5)
    {
        // back arc => [2..3]
        angle = -PI*0.5 + PI*sf;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), -0.25);
    }
    else
    {
        // bottom arc => [3..4], flipped
        angle = -PI + PI*sf;
        p = vec3(-0.25*cos(angle), -0.25, 0.25*sin(angle));
        p = rotateYVec(p, PI*0.5);
    }
    return p;
}

vec3 arcsRawTangent(float t)
{
    float eps = 0.0001;
    vec3 fwd = arcsRawPos(t + eps);
    vec3 bwd = arcsRawPos(t - eps);
    return normalize(fwd - bwd);
}

// Additional transforms from your snippet
vec3 transformArcs(vec3 p)
{
    p = rotateZVec(p, PI/3.2);
    p = rotateYVec(p, PI/4.2);
    p = rotateXVec(p, PI/1.2);
    return p;
}
vec3 transformArcsTangent(vec3 t)
{
    t = rotateZVec(t, PI/3.2);
    t = rotateYVec(t, PI/4.2);
    t = rotateXVec(t, PI/1.2);
    return t;
}

/*****************************************************
 * 4) TREFOIL (knotId=0 => right), closed
 *****************************************************/
vec3 trefoilBasePos(float t)
{
    float s = 0.15;
    return s * vec3(
        sin(t) + 2.0*sin(2.0*t),
        cos(t) - 2.0*cos(2.0*t),
        -sin(3.0*t)
    );
}
vec3 trefoilTangent(float t)
{
    float s = 0.15;
    float dx = cos(t) + 4.0*cos(2.0*t);
    float dy = -sin(t) + 4.0*sin(2.0*t);
    float dz = -3.0*cos(3.0*t);
    return normalize(s * vec3(dx, dy, dz));
}

/*****************************************************
 * 5) RING (knotId=2 => left), closed
 *****************************************************/
vec3 ringBasePos(float t)
{
    float R = 0.26;
    return vec3(R*cos(t), R*sin(t), 0.0);
}
vec3 ringTangent(float t)
{
    float R = 0.26;
    return normalize(vec3(-R*sin(t), R*cos(t), 0.0));
}

/*****************************************************
 * 6) CLOSED or NOT?
 *****************************************************/
bool isKnotClosed(int knotId)
{
    // 0=Trefoil => closed
    // 1=Arcs => NOT closed
    // 2=Ring => closed
    return (knotId != 1);
}

float getKnotTmax(int knotId)
{
    if(knotId == 1) return 4.0; 
    return TWO_PI; 
}

// Per-knot twist
float getKnotTwist(int knotId)
{
    if(knotId == 0) return twistTrefoil; 
    if(knotId == 1) return twistArcs;
    return twistRing;
}

/*****************************************************
 * 7) FRENET-LIKE FRAME
 *****************************************************/
struct FrameData {
    vec3 pos;
    vec3 tangent;
    vec3 normal;
    vec3 binormal;
};

FrameData getKnotFrame(int knotId, float t)
{
    FrameData f;

    if (knotId == 1)  // arcs in the middle
    {
        // raw
        vec3 rp = arcsRawPos(t);
        vec3 rt = arcsRawTangent(t);

        // snippet transform
        rp = transformArcs(rp);
        rt = transformArcsTangent(rt);

        // manual 45° rotation
        rp = rotateXVec(rp, arcsRotX);
        rp = rotateYVec(rp, arcsRotY);
        rp = rotateZVec(rp, arcsRotZ);

        rt = rotateXVec(rt, arcsRotX);
        rt = rotateYVec(rt, arcsRotY);
        rt = rotateZVec(rt, arcsRotZ);

        f.pos     = rp;
        f.tangent = rt;
    }
    else if(knotId == 0) // trefoil => shift right
    {
        vec3 p = trefoilBasePos(t);
        vec3 d = trefoilTangent(t);
        p.x += 1.2; 
        f.pos     = p;
        f.tangent = d;
    }
    else // ring => shift left
    {
        vec3 p = ringBasePos(t);
        vec3 d = ringTangent(t);
        p.x -= 1.2;
        f.pos     = p;
        f.tangent = d;
    }

    // normal & binormal
    vec3 up = vec3(0,1,0);
    vec3 n  = normalize(cross(f.tangent, up));
    if(length(n) < 0.00001)
    {
        up = vec3(1,0,0);
        n  = normalize(cross(f.tangent, up));
    }
    vec3 b = cross(f.tangent, n);

    // scale
    f.pos      *= SCENE_SCALE;
    f.normal   = n;
    f.binormal = b;
    return f;
}

/*****************************************************
 * 8) DOUBLE-WIRE SPIRAL OFFSET
 *****************************************************/
vec3 getWireCenterPos(int knotId, int wireId, float t, float time)
{
    FrameData fd = getKnotFrame(knotId, t);

    float tMax  = getKnotTmax(knotId);
    float u     = t / tMax;
    float twist = getKnotTwist(knotId);

    // wire #1 => phase=0, wire #2 => phase=π
    float phaseShift = (wireId == 0)? 0.0 : PI;

    float twistAngle = ROT_SPEED*time
                     + twist*(u*TWO_PI)
                     + phaseShift;

    // radius for the wire offset
    float radius = 0.03 * SCENE_SCALE;
    vec3 offset = radius * (
        cos(twistAngle)*fd.normal +
        sin(twistAngle)*fd.binormal
    );
    return fd.pos + offset;
}

/*****************************************************
 * 9) CAMERA
 *****************************************************/
struct Camera {
    vec3 ro;
    vec3 forward;
    vec3 right;
    vec3 up;
};

Camera getCamera(float time, vec2 mouse, vec2 resolution)
{
    // start at (0,0,4)
    vec3 baseCam = vec3(0.0, 0.0, 4.0);
    vec3 ro = baseCam;

    // Check if user is clicking
    bool userClicking = (iMouse.z > 0.5); 

    if(!userClicking)
    {
        // AUTO SPIN around Y
        float spin = 0.001 * time;
        ro = rotateYVec(ro, spin);
    }
    else
    {
        // MANUAL ROTATION with mouse
        float yaw   = (mouse.x / resolution.x)*2.0*PI - PI;
        float pitch = (mouse.y / resolution.y)*1.0*PI - 0.5*PI;
        ro = rotateYVec(ro, yaw);
        ro = rotateXVec(ro, pitch);
    }

    // build camera basis
    vec3 fw = normalize(-ro);
    vec3 rt = normalize(cross(fw, vec3(0,1,0)));
    vec3 up = cross(rt, fw);

    Camera c;
    c.ro      = ro;
    c.forward = fw;
    c.right   = rt;
    c.up      = up;
    return c;
}

vec3 projectToScreen(vec3 p3D, Camera cam)
{
    // bigger focal => less perspective
    float focal = 3.5;

    vec3 diff = p3D - cam.ro;
    float cx  = dot(diff, cam.right);
    float cy  = dot(diff, cam.up);
    float cz  = dot(diff, cam.forward);

    if(cz < 0.001) {
        return vec3(9999.0, 9999.0, 9999.0);
    }

    float ndcX = focal * cx / cz;
    float ndcY = focal * cy / cz;
    return vec3(ndcX, ndcY, cz);
}

/*****************************************************
 * 10) DISTANCE FROM PIXEL TO LINE SEGMENT (2D)
 *****************************************************/
float distToSegment2D(vec2 P, vec2 A, vec2 B)
{
    vec2 v  = B - A;
    vec2 w  = P - A;
    float c1 = dot(w,v);
    if(c1 <= 0.0) {
        return length(P - A);
    }
    float c2 = dot(v,v);
    if(c2 <= c1) {
        return length(P - B);
    }
    float b = c1 / c2;
    vec2 Pb = A + b*v;
    return length(P - Pb);
}

/*****************************************************
 * 11) MAIN
 *****************************************************/
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized coords
    vec2 uv = (2.0*fragCoord - iResolution.xy)/iResolution.y;

    // background gradient
    float t = 0.5 * (uv.y + 1.0);
    t = clamp(t, 0.0, 1.0);
    vec3 colTop    = vec3(0.7); // light grey
    vec3 colBottom = vec3(0.6); // mid grey
    vec3 bgColor   = mix(colBottom, colTop, t);

    // camera
    Camera cam = getCamera(iTime, iMouse.xy, iResolution.xy);

    float closestZ = 99999.0;
    vec3  finalColor = bgColor;

    // For each knot
    for(int knotId=0; knotId<KNOT_COUNT; knotId++)
    {
        float tMax   = getKnotTmax(knotId);
        bool  closed = isKnotClosed(knotId);

        // For each wire
        for(int wireId=0; wireId<WIRES_PER_KNOT; wireId++)
        {
            // Subdivide
            for(int i=0; i<N_SAMPLES; i++)
            {
                float t0 = float(i)*(tMax/float(N_SAMPLES));
                float t1 = float(i+1)*(tMax/float(N_SAMPLES));

                // arcs => skip bridging last->0
                if(!closed && i==(N_SAMPLES-1)) {
                    break;
                }
                // skip bridging sub-arcs for arcs
                if(knotId==1) {
                    if(floor(t0) != floor(t1)) {
                        continue;
                    }
                }
                // if closed => wrap last->0
                if(closed && i==(N_SAMPLES-1)) {
                    t1 = 0.0;
                }

                // Evaluate wire
                vec3 p0_3D = getWireCenterPos(knotId, wireId, t0, iTime);
                vec3 p1_3D = getWireCenterPos(knotId, wireId, t1, iTime);

                // project
                vec3 p0_clip = projectToScreen(p0_3D, cam);
                vec3 p1_clip = projectToScreen(p1_3D, cam);

                // both clipped => skip
                if(p0_clip.z>9000.0 && p1_clip.z>9000.0) {
                    continue;
                }

                vec2 a2d = p0_clip.xy;
                vec2 b2d = p1_clip.xy;

                float dist2Line = distToSegment2D(uv, a2d, b2d);
                if(dist2Line < WIRE_RADIUS)
                {
                    float segZ = min(p0_clip.z, p1_clip.z);
                    if(segZ < closestZ)
                    {
                        closestZ = segZ;

                        // wire #1 => yellow, wire #2 => white
                        vec3 baseColor = (wireId == 0)
                                         ? vec3(1.0, 1.0, 0.0)
                                         : vec3(1.0);

                        // small fade from 0.9..1.0
                        float f = 1.0 - clamp(dist2Line / WIRE_RADIUS, 0.0, 1.0);
                        float shade = 0.9 + 0.1*f;

                        // Combine base color with fade
                        vec3 wireColor = baseColor * shade;

                        // -----------------------------------------
                        // --- ADDED: distance-based softening
                        // Option A: direct division by segZ
                        // wireColor = wireColor / segZ;

                        // Option B: avoid extreme blow-outs when segZ < 1
                        wireColor /= (0.9 + 0.03 * segZ);
                        // -----------------------------------------

                        finalColor = wireColor;
                    }
                }
            }
        }
    }

    fragColor = vec4(finalColor, 1.0);
}
